using AstralNexus.Mobile.Data;using AstralNexus.Mobile.Services;
namespace AstralNexus.Mobile.Pages;public partial class ProfilePage:ContentPage{private readonly AppDatabase _db;private readonly SessionService _s;public ProfilePage(AppDatabase db,SessionService s){InitializeComponent();_db=db;_s=s;}protected override async void OnAppearing(){base.OnAppearing();if(!_s.IsLoggedIn)return;var u=await _db.RefreshUserAsync(_s.CurrentUser!.Id);_s.SignIn(u);var stats=await _db.GetStatsAsync(u.Id);NameEntry.Text=u.DisplayName;EmailEntry.Text=u.Email;CreatedLabel.Text=$"Član od: {u.CreatedAtUtc.ToLocalTime():dd.MM.yyyy}";StatsLabel.Text=$"Karte: {stats.OwnedCards} • Špilovi: {stats.Decks} • Pobjede: {stats.Wins}";}private async void Save_Clicked(object s,EventArgs e){var u=_s.CurrentUser!;u.DisplayName=(NameEntry.Text??"").Trim();if(string.IsNullOrWhiteSpace(u.DisplayName)){await DisplayAlert("Profil","Ime ne može biti prazno.","U redu");return;}await _db.UpdateProfileAsync(u);await DisplayAlert("Profil","Podaci su sačuvani.","U redu");}}
